"use client"

import { useRef, useState } from "react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { TabsRoot, TabsList, TabsTrigger } from "@atlas/ui-web/patterns/Tabs/Tabs"
import { mockSubmit } from "../../_shared/mockApi"
import { ORDER_TOTAL, type PaymentStepProps, type Scenario } from "../schema"

type Errors = { cardNumber?: string; expiry?: string; cvc?: string }

const FIELD_ORDER = ["cardNumber", "expiry", "cvc"] as const
const FIELD_IDS = { cardNumber: "pe-card", expiry: "pe-expiry", cvc: "pe-cvc" } as const

const formatCard = (v: string) => v.replace(/\D/g, "").slice(0, 16).replace(/(.{4})/g, "$1 ").trim()
const formatExpiry = (v: string) => {
  const d = v.replace(/\D/g, "").slice(0, 4)
  return d.length > 2 ? `${d.slice(0, 2)}/${d.slice(2)}` : d
}

function validate(card: string, expiry: string, cvc: string): Errors {
  const e: Errors = {}
  if (card.replace(/\D/g, "").length !== 16) e.cardNumber = "Enter the 16 digits on the front of your card."
  const m = /^(\d{2})\/(\d{2})$/.exec(expiry)
  if (!m || +m[1] < 1 || +m[1] > 12) e.expiry = "Enter the expiry as MM/YY."
  if (!/^\d{3,4}$/.test(cvc)) e.cvc = "Enter the 3 or 4 digit security code."
  return e
}

const focusById = (id: string, select = false) => {
  const el = document.getElementById(id) as HTMLInputElement | null
  el?.focus()
  if (select) el?.select()
}

const errorText = {
  margin: 0,
  color: "var(--atlas-danger)",
  fontSize: "var(--atlas-text-caption)",
  marginBlockStart: "var(--atlas-spacing-1)",
} as const

const rule = "var(--atlas-border-width-1) solid var(--atlas-border-subtle)"

export function Payment({ data, patch, next }: PaymentStepProps) {
  const [busy, setBusy] = useState(false)
  const [retrying, setRetrying] = useState(false)
  const [failure, setFailure] = useState<Scenario | null>(null)
  const [errors, setErrors] = useState<Errors>({})
  const [supportShown, setSupportShown] = useState(false)
  // Mock server memory: a declined card keeps declining; a timeout clears on the next attempt.
  const declinedCard = useRef<string | null>(null)
  const timedOut = useRef(false)

  const attempt = async (viaRetry = false) => {
    const found = validate(data.cardNumber, data.expiry, data.cvc)
    setErrors(found)
    const firstBad = FIELD_ORDER.find((k) => found[k])
    if (firstBad) { focusById(FIELD_IDS[firstBad]); return }

    setBusy(true); setRetrying(viaRetry); setFailure(null); setSupportShown(false)
    try {
      const timeout = data.scenario === "timeout"
      await mockSubmit(data, { delayMs: timeout ? 2400 : 1400 })
      if (timeout) {
        if (!timedOut.current) { timedOut.current = true; throw new Error("timeout") }
      } else if (declinedCard.current === null || declinedCard.current === data.cardNumber) {
        declinedCard.current = data.cardNumber
        throw new Error("declined")
      }
      next()
    } catch (e) {
      setFailure((e as Error).message === "timeout" ? "timeout" : "declined")
    } finally {
      setBusy(false); setRetrying(false)
    }
  }

  const changeScenario = (value: string) => {
    patch({ scenario: value as Scenario })
    timedOut.current = false
    declinedCard.current = null
    setFailure(null)
    setSupportShown(false)
  }

  const changeCard = () => {
    setFailure(null)
    focusById(FIELD_IDS.cardNumber, true)
  }

  const supportAction = (
    <Button type="button" size="sm" variant="ghost" onClick={() => setSupportShown(true)}>Contact support</Button>
  )

  return (
    <form
      noValidate
      onSubmit={(e) => { e.preventDefault(); if (!busy) void attempt() }}
      style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)", paddingInline: "var(--atlas-spacing-4)", paddingBlock: "var(--atlas-spacing-4)" }}
    >
      <div>
        <h1 style={{ margin: 0, fontSize: "var(--atlas-text-h2)", fontWeight: "var(--atlas-font-weight-semibold)", color: "var(--atlas-foreground)" }}>Pay for your order</h1>
        <p style={{ margin: 0, marginBlockStart: "var(--atlas-spacing-1)", fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>Enter your card details to finish checking out.</p>
      </div>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", paddingBlock: "var(--atlas-spacing-3)", borderBlock: rule }}>
        <span style={{ fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>Order total</span>
        <span style={{ fontSize: "var(--atlas-text-h3)", fontWeight: "var(--atlas-font-weight-semibold)", color: "var(--atlas-foreground)" }}>{ORDER_TOTAL}</span>
      </div>

      <div>
        <Label htmlFor={FIELD_IDS.cardNumber} required invalid={!!errors.cardNumber}>Card number</Label>
        <Input id={FIELD_IDS.cardNumber} inputMode="numeric" autoComplete="cc-number" placeholder="1234 5678 9012 3456"
          value={data.cardNumber} invalid={!!errors.cardNumber}
          aria-describedby={errors.cardNumber ? "pe-card-error" : undefined}
          onChange={(e) => { patch({ cardNumber: formatCard(e.target.value) }); setErrors((p) => ({ ...p, cardNumber: undefined })) }} />
        {errors.cardNumber && <p id="pe-card-error" style={errorText}>{errors.cardNumber}</p>}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "var(--atlas-spacing-4)" }}>
        <div>
          <Label htmlFor={FIELD_IDS.expiry} required invalid={!!errors.expiry}>Expiry</Label>
          <Input id={FIELD_IDS.expiry} inputMode="numeric" autoComplete="cc-exp" placeholder="MM/YY"
            value={data.expiry} invalid={!!errors.expiry}
            aria-describedby={errors.expiry ? "pe-expiry-error" : undefined}
            onChange={(e) => { patch({ expiry: formatExpiry(e.target.value) }); setErrors((p) => ({ ...p, expiry: undefined })) }} />
          {errors.expiry && <p id="pe-expiry-error" style={errorText}>{errors.expiry}</p>}
        </div>
        <div>
          <Label htmlFor={FIELD_IDS.cvc} required invalid={!!errors.cvc}>CVC</Label>
          <Input id={FIELD_IDS.cvc} inputMode="numeric" autoComplete="cc-csc" placeholder="123"
            value={data.cvc} invalid={!!errors.cvc}
            aria-describedby={errors.cvc ? "pe-cvc-error" : undefined}
            onChange={(e) => { patch({ cvc: e.target.value.replace(/\D/g, "").slice(0, 4) }); setErrors((p) => ({ ...p, cvc: undefined })) }} />
          {errors.cvc && <p id="pe-cvc-error" style={errorText}>{errors.cvc}</p>}
        </div>
      </div>

      {failure === "declined" && (
        <Alert variant="danger" title="Your card was declined"
          description="You haven't been charged. Use a different card, or contact your bank. Your details are still here."
          actions={<>
            <Button type="button" size="sm" variant="primary" onClick={changeCard}>Use a different card</Button>
            {supportAction}
          </>} />
      )}
      {failure === "timeout" && (
        <Alert variant="danger" title="The payment timed out"
          description="We couldn't confirm it went through, so check your email before paying again. Your details are saved; try again in a moment."
          actions={<>
            <Button type="button" size="sm" variant="primary" loading={retrying} onClick={() => void attempt(true)}>Try again</Button>
            {supportAction}
          </>} />
      )}
      {supportShown && (
        <Alert variant="info" title="Support is here to help"
          description="Email support@example.com or call 0800 000 000. Have your order number ready." />
      )}

      <Button type="submit" variant="primary" size="lg" loading={busy && !retrying}>Pay {ORDER_TOTAL} now</Button>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)", paddingBlockStart: "var(--atlas-spacing-3)", borderBlockStart: rule }}>
        <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)" }}>Prototype: simulate failure</span>
        <TabsRoot variant="segmented" size="sm" value={data.scenario} onValueChange={changeScenario}>
          <TabsList aria-label="Simulate failure">
            <TabsTrigger value="declined">Card declined</TabsTrigger>
            <TabsTrigger value="timeout">Network timeout</TabsTrigger>
          </TabsList>
        </TabsRoot>
      </div>
    </form>
  )
}

