      title="Payment"
      step={flow.step}
      totalSteps={PAYMENT_STEPS.length}
      onReset={flow.reset}
      phoneBackground="var(--atlas-background)"
    >
      {key === "payment" && <Payment {...props} />}
      {key === "done" && <Done {...props} />}
    </FlowShell>
  )
}
